namespace CheckoutPricing.Domain;

public static class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier loyaltyTier, bool express) =>
        express ? ExpressFee(loyaltyTier) : StandardFee(payableTotalCents, loyaltyTier);

    private static int ExpressFee(LoyaltyTier loyaltyTier) =>
        loyaltyTier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFee(int payableTotalCents, LoyaltyTier loyaltyTier) =>
        payableTotalCents >= FreeStandardFromCents || loyaltyTier is LoyaltyTier.Gold or LoyaltyTier.Platinum
            ? 0
            : StandardFeeCents;
}

arguments.new_str:
public CheckoutQuote Handle(QuoteCheckoutQuery query)
{
    var discount = new CalculateLoyaltyDiscount().Handle(
        new CalculateLoyaltyDiscountQuery(query.SubtotalCents, query.LoyaltyTier, query.PromoCode));
    var shippingCents = new CalculateShippingFee().Handle(
        new CalculateShippingFeeQuery(discount.TotalCents, query.LoyaltyTier, query.Express));

    return new(discount.TotalCents, shippingCents, discount.TotalCents + shippingCents);
}

